);", "examples": [{"id": "C:document_management:hard:1:98:0", "question": "Quels sont les noms des documents dont le code figure parmi les codes de document enregistrés dans les documents ?", "sql": "SELECT document_name FROM Documents WHERE document_code IN (SELECT document_code FROM Documents)"}, {"id": "C:document_management:hard:1:98:1", "question": "Quels codes de document sont associés aux documents dont le code apparaît dans l'ensemble des codes de document ?", "sql": "SELECT document_code FROM Documents WHERE document_code IN (SELECT document_code FROM Documents)"}, {"id": "C:document_management:hard:1:98:2", "question": "Quelles structures documentaires sont désignées par des codes de structure présents dans les structures documentaires ?", "sql": "SELECT document_structure_description FROM Document_Structures WHERE document_structure_code IN (SELECT document_structure_code FROM Document_Structures)"}, {"id": "C:document_management:hard:1:98:3", "question": "Quels codes de structure documentaire correspondent à des codes de structure existant dans la table des structures ?", "sql": "SELECT document_structure_code FROM Document_Structures WHERE document_structure_code IN (SELECT document_structure_code FROM Document_Structures)"}, {"id": "C:document_management:hard:1:98:4", "question": "Quelles descriptions de domaines fonctionnels correspondent à des codes de domaine présents dans les domaines fonctionnels ?", "sql": "SELECT functional_area_description FROM Functional_Areas WHERE functional_area_code IN (SELECT functional_area_code FROM Functional_Areas)"}, {"id": "C:document_management:hard:1:98:5", "question": "Quels codes de domaines fonctionnels apparaissent parmi les codes de domaines fonctionnels enregistrés ?", "sql": "SELECT functional_area_code FROM Functional_Areas WHERE functional_area_code IN (SELECT functional_area_code FROM Functional_Areas)"}, {"id": "C:document_management:hard:1:98:6", "question": "Quels noms d'images correspondent à des identifiants présents dans la table des images ?", "sql": "SELECT image_name FROM Images WHERE image_id IN (SELECT image_id FROM Images)"}, {"id": "C:document_management:hard:1:98:7", "question": "Quels textes alternatifs sont associés à des identifiants d'image figurant dans les images enregistrées ?", "sql": "SELECT image_alt_text FROM Images WHERE image_id IN (SELECT image_id FROM Images)"}, {"id": "C:document_management:hard:1:98:8", "question": "Quelles URL d'images sont liées à des identifiants existant dans l'ensemble des images ?", "sql": "SELECT image_url FROM Images WHERE image_id IN (SELECT image_id FROM Images)"}, {"id": "C:document_management:hard:1:98:9", "question": "Quels codes de rôle correspondent à des codes présents dans la table des rôles ?", "sql": "SELECT role_code FROM Roles WHERE role_code IN (SELECT role_code FROM Roles)"}, {"id": "C:document_management:hard:1:98:10", "question": "Quelles descriptions de rôles sont associées à des codes de rôle enregistrés ?", "sql": "SELECT role_description FROM Roles WHERE role_code IN (SELECT role_code FROM Roles)"}, {"id": "C:document_management:hard:1:98:11", "question": "Quels noms d'utilisateurs correspondent à des identifiants présents dans la table des utilisateurs ?", "sql": "SELECT user_name FROM Users WHERE user_id IN (SELECT user_id FROM Users)"}, {"id": "C:document_management:hard:1:98:12", "question": "Quels identifiants de connexion appartiennent à des utilisateurs dont l'identifiant figure parmi les identifiants enregistrés ?", "sql": "SELECT user_login FROM Users WHERE user_id IN (SELECT user_id FROM Users)"}, {"id": "C:document_management:extra:1:99:0", "question": "Combien de documents de chaque structure ont un accès positif et ne sont pas du type rapport ?", "sql": "SELECT document_structure_code, COUNT(*) FROM Documents WHERE access_count > 0 AND document_type_code != 'rapport' GROUP BY document_structure_code"}, {"id": "C:document_management:extra:1:99:1", "question": "Pour chaque type de document, combien de documents ont au moins un accès et un nom renseigné ?", "sql": "SELECT document_type_code, COUNT(*) FROM Documents WHERE access_count > 0 AND document_name != '' GROUP BY document_type_code"}, {"id": "C:document_management:extra:1:99:2", "question": "Combien de sections de chaque document ont un numéro de séquence positif et un titre renseigné ?", "sql": "SELECT document_code, COUNT(*) FROM Document_Sections WHERE section_sequence > 0 AND section_title != '' GROUP BY document_code"}, {"id": "C:document_management:extra:1:99:3", "question": "Pour chaque code de section, combien d’enregistrements concernent des documents différents de DOC001 et ont une séquence positive ?", "sql": "SELECT section_code, COUNT(*) FROM Document_Sections WHERE document_code != 'DOC001' AND section_sequence > 0 GROUP BY section_code"}, {"id": "C:document_management:extra:1:99:4", "question": "Combien d’associations concernent chaque zone fonctionnelle lorsque le document n’est pas DOC001 et la zone n’est pas FA001 ?", "sql": "SELECT functional_area_code, COUNT(*) FROM Document_Functional_Areas WHERE document_code != 'DOC001' AND functional_area_code != 'FA001' GROUP BY functional_area_code"}, {"id": "C:document_management:extra:1:99:5", "question": "Pour chaque document, combien de ses associations fonctionnelles concernent une zone différente de FA001 et un code de document différent de DOC999 ?", "sql": "SELECT document_code, COUNT(*) FROM Document_Functional_Areas WHERE functional_area_code != 'FA001' AND document_code != 'DOC999' GROUP BY document_code"}, {"id": "C:document_management:extra:1:99:6", "question": "Combien de structures parentes différentes sont associées à chaque description non vide et à un code différent de STR001 ?", "sql": "SELECT parent_document_structure_code, COUNT(*) FROM Document_Structures WHERE document_structure_description != '' AND document_structure_code != 'STR001' GROUP BY parent_document_structure_code"}, {"id": "C:document_management:extra:1:99:7", "question": "Pour chaque code de structure, combien d’entrées ont une description renseignée et un parent différent de STR999 ?", "sql": "SELECT document_structure_code, COUNT(*) FROM Document_Structures WHERE document_structure_description != '' AND parent_document_structure_code != 'STR999' GROUP BY document_structure_code"}, {"id": "C:document_management:extra:1:99:8", "question": "Combien de zones fonctionnelles de chaque parent ont une description renseignée et un code différent de FA001 ?", "sql": "SELECT parent_functional_area_code, COUNT(*) FROM Functional_Areas WHERE functional_area_description != '' AND functional_area_code != 'FA001' GROUP BY parent_functional_area_code"}, {"id": "C:document_management:extra:1:99:9", "question": "Pour chaque zone fonctionnelle, combien d’entrées ont un parent différent de FA999 et une description non vide ?", "sql": "SELECT functional_area_code, COUNT(*) FROM Functional_Areas WHERE parent_functional_area_code != 'FA999' AND functional_area_description != '' GROUP BY functional_area_code"}, {"id": "C:document_management:extra:1:99:10", "question": "Combien d’images de chaque identifiant positif ont un nom renseigné et une URL différente de vide ?", "sql": "SELECT image_id, COUNT(*) FROM Images WHERE image_id > 0 AND image_name != '' GROUP BY image_id"}, {"id": "C:document_management:extra:1:99:11", "question": "Pour chaque nom d’image, combien d’images ont un identifiant positif et un texte alternatif renseigné ?", "sql": "SELECT image_name, COUNT(*) FROM Images WHERE image_id > 0 AND image_alt_text != '' GROUP BY image_name"}]}

