 FROM review)"}, {"id": "C:epinions_1:extra:1:117:0", "question": "Combien d'avis chaque utilisateur a-t-il publiés avec une note au moins égale à 4 et un rang au plus égal à 100?", "sql": "SELECT u_id, COUNT(*) FROM review WHERE rating >= 4 AND rank <= 10 GROUP BY u_id"}, {"id": "C:epinions_1:extra:1:117:1", "question": "Pour chaque article, combien d'avis ont une note différente de 1 et un rang supérieur à 00?", "sql": "SELECT i_id, COUNT(*) FROM review WHERE rating != 1 AND rank > 0 GROUP BY i_id"}, {"id": "C:epinions_1:extra:1:117:2", "question": "Combien d'avis correspondent à chaque note lorsque l'identifiant de l'utilisateur est supérieur à 100 et celui de l'article inférieur à 5000?", "sql": "SELECT rating, COUNT(*) FROM review WHERE u_id > 100 AND i_id < 500 GROUP BY rating"}, {"id": "C:epinions_1:extra:1:117:3", "question": "Pour chaque rang, combien d'avis ont reçu la note maximale de 5 et proviennent d'un utilisateur dont l'identifiant est différent de 00?", "sql": "SELECT rank, COUNT(*) FROM review WHERE rating = 5 AND u_id != 0 GROUP BY rank"}, {"id": "C:epinions_1:extra:1:117:4", "question": "Combien d'articles portent chaque titre, en ne retenant que les identifiants supérieurs à 10 et les titres différents de «0Unknown0»0?", "sql": "SELECT title, COUNT(*) FROM item WHERE i_id > 10 AND title != 'Unknown' GROUP BY title"}, {"id": "C:epinions_1:extra:1:117:5", "question": "Pour chaque identifiant d'article, combien d'articles ont le titre «0Camera0» et un identifiant au moins égal à 10?", "sql": "SELECT i_id, COUNT(*) FROM item WHERE title = 'Camera' AND i_id >= 1 GROUP BY i_id"}, {"id": "C:epinions_1:extra:1:117:6", "question": "Combien de relations de confiance chaque utilisateur source possède-t-il vers des cibles dont l'identifiant est inférieur à 500, avec une confiance au moins égale à 10?", "sql": "SELECT source_u_id, COUNT(*) FROM trust WHERE target_u_id < 500 AND trust >= 1 GROUP BY source_u_id"}, {"id": "C:epinions_1:extra:1:117:7"